#' tastats.boot
#'
#' Returns sample-level equi-tailed two-sided bootstrap confidence
#' intervals for time-averaging statistics. Accepts object of the
#' class 'postidst' generated by function \code{\link{postdist}}
#'
#' @details Calculates accelerated-bias-corrected non-parametric bootstrap
#' confidence intervals for each sample of dated specimens using
#' functions \code{\link[boot]{boot}} and \code{\link[boot]{boot.ci}}
#' from package "boot".
#'
#' Currently, the following statistics can be returned:
#'
#' ETA - bootstrap estimate of confidence intervals for
#' Estimated Time-Averaging  corrected for dating uncertainty
#' calculated as 2 * square root of TAV-AEV (see Ritter et al. 2023)
#'
#' IQR - bootstrap estimate IQR corrected for dating uncertainty computed
#' as ETA/2 multiplied by iq.age/std.age (see Tomasovych et al. 2023)
#'
#' g1 - bootstrap estimate of skewness, the third moment about the mean calculated from mean or
#' median ages of posterior distributions
#'
#' l3 - bootstrap estimate of L-skeweness calculated using
#' function \code{\link[lmom]{samlmu}} from package "lmom".
#'
#' @param x An object of class 'postdist' returned by \code{\link{postdist}} function
#'
#' @param param A character string (default='ETA') selecting the statistic
#' to be analyzed: 'l3' - l-moment skewness, 'ETA' - estimated time-averaging
#' ('ETA' also returns confidence intervals for IQR estimate)
#'
#' @param iter A numerical value (default=100) defining the number of
#' replicate pseudo-samples that will be generated to derive bootstrap
#' estimates
#'
#' @param conf A scalar or vector specifying confidence intervals.
#' The default c(0.5, 0.95, 0.99).
#'
#' @return A dataframe with the sample estimate of the
#' statistic ('ETA/IQR' or 'l3) and sample-level bootstrap confidence
#' intervals:
#'   \item{cf}{returns a dataframe with estimates of the statistic and
#'    lower and upper bootstrap confidence limits}
#'
#' @examples
#'
#' out1 <- postdist(age=florida$post$cal.BP, prob=florida$post$probability,
#' id=florida$post$UniqueID, size=1000)
#'
#' out2 <- tastats.boot(out1, param='ETA', iter=100)
#' out2
#'
#' @importFrom boot boot boot.ci
#' @importFrom lmom samlmu
#' @importFrom stats var sd median IQR
#'
#' @export
#'
#' @references Angelo Canty and Brian Ripley (2024). boot:
#' Bootstrap R (S-Plus) Functions. R package version 1.3-31.
#'
#' Davison, A. C. & Hinkley, D. V. (1997) Bootstrap Methods and
#' Their Applications. Cambridge University Press, Cambridge.
#' ISBN 0-521-57391-2
#'
#' Hosking, JRM, 2023, L-Moments. R package, version 3.0.
#' https://CRAN.R-project.org/package=lmom
#'
#' Ritter, M, Erthal F, Kosnik, MA, Kowalewski, M, Coimbra, CJ,
#' Caron, F, Kaufman, DS, 2023, Onshore-offshore trends in the temporal
#' resolution of molluscan death assemblages: how age-frequency
#' distributions reveal Quaternary sea-level history.
#' Palaios, 38: 148-157. http://dx.doi.org/10.2110/palo.2021.041
#'
#' Tomašových, A., Kidwell, S.M. and Dai, R., (2023), A downcore increase
#' in time averaging is the null expectation from the transit of death assemblages
#' through a mixed layer. Paleobiology, 49(3), pp.527-562.
#' https://doi.org/10.1017/pab.2022.42
#'

tastats.boot <- function(x, param='ETA', iter=100, conf=c(0.5, 0.95, 0.99)) {
# if (!('postdist' %in% class(x))) warning('object of the class "postdist" is required')
    if (param == 'ETA') {
      ETA.boot.F <- function(x, w) {
        2*sqrt(var(as.vector(x[w,])) - mean(apply(x[w,], 1, var)))
      }
      boot.out <- boot::boot(x, ETA.boot.F, R=iter)
      ci.out <- suppressWarnings(boot::boot.ci(boot.out, type='bca', conf=conf))
      corr.IQR <- IQR(apply(x, 1, median))/sd(apply(x, 1, median))
      ci.out2 <- rbind(rep(ci.out$t0, 2), rep(corr.IQR, 2),
                       rep(ci.out$t0*corr.IQR, 2), ci.out$bca[,4:5],
                       ci.out$bca[,4:5]*corr.IQR)
      rownames(ci.out2) <- c('ETA-estimate', 'IQRcorr', 'IQR-estimate', paste0('ETA-', conf),
                             paste0('IQR-', conf))
      colnames(ci.out2) <- c('lower limit', 'upper limit')
    }

    if (param == 'l3') {
      l3F <- function(x) as.numeric(lmom::samlmu(x)[3])
      L3.boot.F <- function(x, w) l3F(apply(x[w,], 1, median))
      boot.out <- boot::boot(x, L3.boot.F, R=iter)
      ci.out <- suppressWarnings(boot::boot.ci(boot.out, type='bca', conf=conf))
      ci.out2 <- rbind(rep(ci.out$t0, 2), ci.out$bca[,4:5])
      rownames(ci.out2) <- c('L3-estimate', paste0('L3-', conf))
      colnames(ci.out2) <- c('lower limit', 'upper limit')
    }
    return(cf=data.frame(t(ci.out2)))
}

